// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    // fuzz the caller address; the property concerns calls made by the contract owner
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid zero address which is not useful as EOA owner
        vm.assume(caller != address(0));

        // The owner of c is the deployer from setUp() i.e., address(this) as Test uses the test contract
        // We will let the fuzzer provide `caller`; we only care that when the owner (address(this)) calls,
        // the correct contract's sudicideAnyone() completes (does not revert). The mutant with require(false)
        // will revert even for the owner, so the property is violated for that input (owner caller).

        // Make a call as the fuzzer-supplied caller to show non-owner calls revert due to __onlyOwner.
        bool okNonOwner;
        try c.sudicideAnyone{gas: gasleft()}() {
            okNonOwner = true;
        } catch {
            okNonOwner = false;
        }
        // Non-owner should not be able to successfully call; either revert or succeed depending on caller.
        // We don't assert on this outcome; it's just exercised.

        // Now, the general rule we assert: when the OWNER calls sudicideAnyone(), the call completes (no revert).
        // The owner is the address that deployed c in setUp(), which is address(this).
        bool okOwner;
        // impersonate owner (address(this) is already msg.sender if we call directly, but to follow patterns we use prank)
        vm.startPrank(address(this));
        try c.sudicideAnyone{gas: gasleft()}() {
            okOwner = true;
        } catch {
            okOwner = false;
        }
        vm.stopPrank();

        // The correct contract always allows the owner call to succeed. The mutant with require(false) breaks this.
        assertTrue(okOwner);
    }
}
